"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { useState } from "react";

export default function TaskItem({ id, columnId, text, onDelete, onEdit }: any) {
  const { setNodeRef, attributes, listeners, transform, transition } = useSortable({
    id,
    data: { column: columnId },
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const [isEditing, setIsEditing] = useState(false);
  const [value, setValue] = useState(text);

  const saveEdit = () => {
    onEdit(id, value);
    setIsEditing(false);
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="p-3 bg-gray-700 text-white rounded-lg shadow hover:scale-[1.02] transition cursor-grab relative"
    >
      {isEditing ? (
        <div className="flex flex-col gap-2">
          <input
            value={value}
            onChange={(e) => setValue(e.target.value)}
            className="p-2 rounded-md text-black"
            autoFocus
          />
          <div className="flex justify-end gap-2">
            <button onClick={saveEdit} className="px-3 py-1 bg-blue-600 rounded-md text-white hover:bg-blue-700">
              Opslaan
            </button>
            <button onClick={() => setIsEditing(false)} className="px-3 py-1 bg-gray-500 rounded-md text-white hover:bg-gray-600">
              Annuleren
            </button>
          </div>
        </div>
      ) : (
        <>
          <span>{text}</span>
          <div className="absolute top-2 right-2 flex gap-1">
            <button onClick={() => setIsEditing(true)} className="px-2 py-1 text-sm bg-gray-500 rounded hover:bg-gray-600">
              ✏️
            </button>
            <button onClick={() => onDelete(id)} className="px-2 py-1 text-sm bg-red-600 rounded hover:bg-red-700">
              🗑️
            </button>
          </div>
        </>
      )}
    </div>
  );
}